return ['domain'=>NULL,'plural-forms'=>'nplurals=2; plural=n != 1;','language'=>'hi_IN','project-id-version'=>'Babilim 2.2.0','pot-creation-date'=>'2026-11-09T07:54:21+00:00','po-revision-date'=>'2026-11-09T07:54:21+00:00','x-generator'=>'Babilim','messages'=>['Sent when you press Enable Babilim, and again if the site has to register anew: your site\'s URL, the WordPress, PHP and Babilim versions, the language of your site and the languages in use on it, and a public key generated for this site.'=>'यह तब भेजा जाता है जब आप Babilim सक्षम करें दबाते हैं, और साइट को दोबारा पंजीकरण करना पड़े तब भी: आपकी साइट का यूआरएल, WordPress, PHP और Babilim के संस्करण, आपकी साइट की भाषा और उस पर उपयोग में आने वाली भाषाएँ, तथा इस साइट के लिए बनाई गई एक सार्वजनिक कुंजी।','Sent on every check: the list of installed plugins and themes with the state of any Babilim translation installed for them, the languages in use, and short diagnostic codes.'=>'हर जाँच पर भेजा जाता है: स्थापित प्लगइन और थीम की सूची, उनके लिए स्थापित किसी भी Babilim अनुवाद की स्थिति के साथ, उपयोग में आने वाली भाषाएँ, और छोटे डायग्नोस्टिक कोड।','Every request includes your site\'s URL, and the site\'s access token is included whenever the service needs it.'=>'हर अनुरोध में आपकी साइट का यूआरएल शामिल होता है, और जब भी सेवा को ज़रूरत होती है, साइट का एक्सेस टोकन भी शामिल किया जाता है।','What Babilim sends to the service'=>'Babilim सेवा को क्या भेजता है','Your site\'s URL'=>'आपकी साइट का यूआरएल','WordPress version'=>'WordPress संस्करण','PHP version'=>'PHP संस्करण','Babilim version'=>'Babilim संस्करण','Your site\'s language'=>'आपकी साइट की भाषा','Languages in use on your site'=>'आपकी साइट पर उपयोग में आने वाली भाषाएँ','A public key for this site'=>'इस साइट के लिए एक सार्वजनिक कुंजी','A public key generated for this site, used to prove requests genuinely come from this site. Only the public half is ever sent; the private half stays on your site.'=>'इस साइट के लिए बनाई गई एक सार्वजनिक कुंजी, जिसका उपयोग यह प्रमाणित करने के लिए होता है कि अनुरोध वास्तव में इसी साइट से आए हैं। केवल सार्वजनिक भाग ही भेजा जाता है; निजी भाग आपकी साइट पर ही रहता है।','Installed plugins and themes'=>'स्थापित प्लगइन और थीम','Source files (only if you confirm an upload)'=>'स्रोत फ़ाइलें (केवल यदि आप अपलोड की पुष्टि करते हैं)','Diagnostic codes'=>'डायग्नोस्टिक कोड','Up to 20 short diagnostic codes (for example, a translation file that failed its check), each with the plugin or theme, the language and the time it happened. They never contain any text from your site or any translated text.'=>'अधिकतम 20 छोटे डायग्नोस्टिक कोड (उदाहरण के लिए, कोई अनुवाद फ़ाइल जो अपनी जाँच में विफल रही), हर एक के साथ प्लगइन या थीम, भाषा और वह समय जब यह हुआ। इनमें आपकी साइट का कोई टेक्स्ट या कोई अनूदित टेक्स्ट कभी शामिल नहीं होता।','%1$d site on this network is set to erase its Babilim identity when the plugin is deleted. The paid license attached to that site could then not be restored automatically; you would have to contact Babilim support at %2$s. To keep the identity, press Cancel, untick "Delete all Babilim data on uninstall" in that site\'s Babilim settings, and deactivate again. Deactivate anyway?'=>'इस नेटवर्क की %1$d साइट प्लगइन हटाए जाने पर अपनी Babilim पहचान मिटाने के लिए सेट है। तब उस साइट से जुड़ा सशुल्क लाइसेंस अपने-आप बहाल नहीं किया जा सकेगा; आपको %2$s पर Babilim सहायता से संपर्क करना होगा। पहचान बनाए रखने के लिए रद्द करें दबाएँ, उस साइट की Babilim सेटिंग्स में "अनइंस्टॉल करने पर Babilim का सारा डेटा हटाएँ" का चयन हटाएँ, और फिर से निष्क्रिय करें। फिर भी निष्क्रिय करें?' . "\0" . 'इस नेटवर्क की %1$d साइटें प्लगइन हटाए जाने पर अपनी Babilim पहचान मिटाने के लिए सेट हैं। तब उन साइटों से जुड़ा सशुल्क लाइसेंस अपने-आप बहाल नहीं किया जा सकेगा; आपको %2$s पर Babilim सहायता से संपर्क करना होगा। पहचानें बनाए रखने के लिए रद्द करें दबाएँ, हर साइट की Babilim सेटिंग्स में "अनइंस्टॉल करने पर Babilim का सारा डेटा हटाएँ" का चयन हटाएँ, और फिर से निष्क्रिय करें। फिर भी निष्क्रिय करें?','%1$s %2$s.'=>'%1$s %2$s.','%1$s (%2$s): %3$s'=>'%1$s (%2$s): %3$s','%1$s nothing to do.'=>'%1$s करने के लिए कुछ नहीं है।','%1$s: %2$s'=>'%1$s: %2$s','%1$s: %2$s (%3$s)'=>'%1$s: %2$s (%3$s)','%1$s: %2$s. Choose the language.'=>'%1$s: %2$s। भाषा चुनें।','%d failed'=>'%d विफल रहे' . "\0" . '%d विफल रहे','%d not yet tried'=>'%d का अभी प्रयास नहीं हुआ' . "\0" . '%d का अभी प्रयास नहीं हुआ','%d report is waiting. "Always share" and "Don\'t share" apply to all of them.'=>'%d रिपोर्ट प्रतीक्षा में है। "Always share" और "Don\'t share" उन सभी पर लागू होते हैं।' . "\0" . '%d रिपोर्ट प्रतीक्षा में हैं। "Always share" और "Don\'t share" उन सभी पर लागू होते हैं।','%d skipped'=>'%d छोड़े गए' . "\0" . '%d छोड़े गए','%d succeeded'=>'%d सफल रहे' . "\0" . '%d सफल रहे','%d to install'=>'%d स्थापित करने के लिए' . "\0" . '%d स्थापित करने के लिए','(a public key generated for this site)'=>'(इस साइट के लिए बनाई गई एक सार्वजनिक कुंजी)','(detected)'=>'(पता लगाया गया)','(generic codes and coordinates only)'=>'(केवल सामान्य कोड और निर्देशांक)','A cleanup was paused on %1$s: %2$s. Nothing was deleted.'=>'%1$s को एक सफ़ाई रोक दी गई: %2$s। कुछ भी हटाया नहीं गया।','A file in the component could not be read, so it was not packaged.'=>'घटक की एक फाइल पढ़ी नहीं जा सकी, इसलिए उसे पैकेज में शामिल नहीं किया गया।','A host that serves only one PHP request at a time cannot complete this step.'=>'जो होस्ट एक समय में केवल एक PHP अनुरोध संभालता है, वह यह चरण पूरा नहीं कर सकता।','A part of the upload kept failing, so the upload was cancelled.'=>'अपलोड का एक हिस्सा बार-बार विफल होता रहा, इसलिए अपलोड रद्द कर दिया गया।','A translation cannot be requested for that locale on this site right now.'=>'इस साइट पर अभी उस लोकेल के लिए अनुवाद का अनुरोध नहीं किया जा सकता।','A translation-index write conflicted with another request on %1$s (%2$s) and was not applied; the most recent version was kept.'=>'अनुवाद अनुक्रमणिका में लिखने का एक प्रयास %1$s पर (%2$s) किसी अन्य अनुरोध से टकरा गया और लागू नहीं किया गया; सबसे हाल का संस्करण रखा गया।','A translation-index write on %1$s (%2$s) could not be completed and was not applied (%3$s).'=>'%1$s पर (%2$s) अनुवाद अनुक्रमणिका में लिखना पूरा नहीं हो सका और लागू नहीं किया गया (%3$s)।','Account'=>'खाता','Add another language'=>'एक और भाषा जोड़ें','Advanced'=>'उन्नत','All'=>'सभी','All free-plan slots for this site are used'=>'इस साइट के सभी निःशुल्क प्लान स्लॉट उपयोग में हैं','All languages'=>'सभी भाषाएँ','Already in WordPress core'=>'WordPress कोर में पहले से मौजूद','Already installed.'=>'पहले से स्थापित है।','Always share'=>'Always share','Another installation is running; try again in a moment.'=>'एक और इंस्टॉलेशन चल रहा है; कृपया कुछ देर बाद पुनः प्रयास करें।','Automatic installs'=>'स्वचालित इंस्टॉल','Automatic installs are now off; turn them on again in the settings if you want them.'=>'स्वचालित इंस्टॉल अब बंद हैं; यदि आप चाहें तो उन्हें सेटिंग्स में फिर से चालू करें।','Available'=>'उपलब्ध','Available translations can be installed with one click, and missing ones can be requested. While automatic installs are on, translations the service lists as available for the languages you manage are installed during the twice-daily sync.'=>'उपलब्ध अनुवाद एक क्लिक में स्थापित किए जा सकते हैं, और अनुपलब्ध अनुवादों का अनुरोध किया जा सकता है। स्वचालित इंस्टॉल चालू रहने पर, आपके द्वारा प्रबंधित भाषाओं के लिए सेवा द्वारा उपलब्ध बताए गए अनुवाद दिन में दो बार होने वाले सिंक के दौरान स्थापित किए जाते हैं।','Available · %s'=>'उपलब्ध · %s','Babilim'=>'Babilim','Babilim adds translations for every language checked here.'=>'यहाँ चयनित प्रत्येक भाषा के लिए Babilim अनुवाद जोड़ता है।','Babilim could not confirm a temporary folder outside the website, so the component was not packaged and nothing was uploaded. Define BABILIM_TEMP_DIR in wp-config.php as a writable folder outside the web root (for example a folder next to, not inside, your site\'s public directory), or ask your host for one.'=>'Babilim वेबसाइट के बाहर अस्थायी फ़ोल्डर की पुष्टि नहीं कर सका, इसलिए कॉम्पोनेंट का पैकेज नहीं बनाया गया और कुछ भी अपलोड नहीं हुआ। wp-config.php में BABILIM_TEMP_DIR को वेब रूट के बाहर लिखने योग्य फ़ोल्डर के रूप में परिभाषित करें (उदाहरण के लिए आपकी साइट की सार्वजनिक डायरेक्टरी के अंदर नहीं, बल्कि उसके बगल में बना फ़ोल्डर), या अपने होस्ट से एक माँगें।','Babilim could not finish checking this site.'=>'Babilim इस साइट की जांच पूरी नहीं कर सका।','Babilim could not finish enabling (%1$s): %2$s'=>'Babilim सक्षम होने की प्रक्रिया पूरी नहीं कर सका (%1$s): %2$s','Babilim could not finish verifying this site (the service could not reach it back). Registration is paused.'=>'Babilim इस साइट का सत्यापन पूरा नहीं कर सका (सेवा इस तक वापस नहीं पहुँच सकी)। पंजीकरण रोक दिया गया है।','Babilim could not verify this site, so nothing is downloaded or installed until verification succeeds.'=>'Babilim इस साइट को सत्यापित नहीं कर सका, इसलिए सत्यापन सफल होने तक कुछ भी डाउनलोड या स्थापित नहीं किया जाएगा।','Babilim could not verify this site, so nothing is downloaded or installed.'=>'Babilim इस साइट को सत्यापित नहीं कर सका, इसलिए कुछ भी डाउनलोड या स्थापित नहीं किया गया।','Babilim gets translations from the Babilim service for the plugins and themes on this site that have none for your language, and installs the ones your service plan covers.'=>'Babilim इस साइट के उन प्लगइन और थीम के अनुवाद Babilim सेवा से प्राप्त करता है जिनका आपकी भाषा में कोई अनुवाद नहीं है, और आपकी सेवा योजना में शामिल अनुवादों को स्थापित करता है।','Babilim has not been enabled for this site yet.'=>'इस साइट के लिए Babilim अभी तक सक्षम नहीं किया गया है।','Babilim has not installed any translation for this language.'=>'Babilim ने इस भाषा के लिए कोई अनुवाद स्थापित नहीं किया है।','Babilim hit an error. Share an error report?'=>'Babilim में त्रुटि हुई। क्या त्रुटि रिपोर्ट साझा करें?','Babilim installed %d translation automatically since your last visit.'=>'आपकी पिछली विज़िट के बाद से Babilim ने %d अनुवाद स्वचालित रूप से स्थापित किया।' . "\0" . 'आपकी पिछली विज़िट के बाद से Babilim ने %d अनुवाद स्वचालित रूप से स्थापित किए।','Babilim is disabled. Nothing more is sent; translations already installed keep working.'=>'Babilim अक्षम है। अब कुछ और नहीं भेजा जाएगा; पहले से स्थापित अनुवाद काम करते रहेंगे।','Babilim is enabled: this site is verified and %d component was found.'=>'Babilim सक्षम है: यह साइट सत्यापित है और %d घटक मिला।' . "\0" . 'Babilim सक्षम है: यह साइट सत्यापित है और %d घटक मिले।','Babilim is enabling and checking this site… (last attempt: %s)'=>'Babilim इस साइट को सक्षम करके जाँच रहा है… (अंतिम प्रयास: %s)','Babilim is enabling and checking this site… Reload this page or wait for the scheduled check to finish.'=>'Babilim इस साइट को सक्षम करके जाँच रहा है… इस पृष्ठ को रीलोड करें या निर्धारित जाँच पूरी होने की प्रतीक्षा करें।','Babilim is not enabled.'=>'Babilim सक्षम नहीं है।','Babilim is set to erase this site\'s identity when the plugin is deleted. The paid license attached to this site could then not be restored automatically; you would have to contact Babilim support at %s. To keep the identity, press Cancel, untick "Delete all Babilim data on uninstall" in the Babilim settings, and deactivate again. Deactivate anyway?'=>'प्लगइन हटाए जाने पर Babilim इस साइट की पहचान मिटाने के लिए सेट है। तब इस साइट से जुड़ा सशुल्क लाइसेंस अपने-आप बहाल नहीं किया जा सकेगा; आपको %s पर Babilim सहायता से संपर्क करना होगा। पहचान बनाए रखने के लिए रद्द करें दबाएँ, Babilim सेटिंग्स में "अनइंस्टॉल करने पर Babilim का सारा डेटा हटाएँ" का चयन हटाएँ, और फिर से निष्क्रिय करें। फिर भी निष्क्रिय करें?','Babilim ran out of time for this step and will continue on the next check.'=>'इस चरण के लिए Babilim का समय समाप्त हो गया है और वह अगली जांच के दौरान काम जारी रखेगा।','Babilim settings'=>'Babilim सेटिंग्स','Babilim sync is temporarily delayed by the service (rate limited); it will try again after %s.'=>'सेवा द्वारा Babilim सिंक अस्थायी रूप से विलंबित है (दर सीमित); यह %s के बाद फिर प्रयास करेगा।','Babilim was updated while this upload was waiting. The old package was discarded; please confirm the upload again.'=>'इस अपलोड के प्रतीक्षा में रहने के दौरान Babilim अपडेट हो गया। पुराना पैकेज हटा दिया गया है; कृपया अपलोड की फिर से पुष्टि करें।','Babilim will upload these files from %1$s (version %2$s): every .php and .js file, every block.json file, and the readme.txt, readme.md, style.css and theme.json in its main folder. They are used to find the text that needs translating and to identify the plugin or theme.'=>'Babilim %1$s (संस्करण %2$s) की ये फ़ाइलें अपलोड करेगा: हर .php और .js फ़ाइल, हर block.json फ़ाइल, और इसके मुख्य फ़ोल्डर की readme.txt, readme.md, style.css और theme.json। इनका उपयोग अनुवाद योग्य टेक्स्ट खोजने और प्लगइन या थीम की पहचान करने के लिए किया जाता है।','Babilim_Manifest is unavailable: %s'=>'Babilim_Manifest उपलब्ध नहीं है: %s','Back'=>'वापस जाएँ','Bought a license for this domain before? Enter the restore code you received at checkout.'=>'क्या आपने इस डोमेन के लिए पहले लाइसेंस खरीदा था? भुगतान के समय मिला रीस्टोर कोड दर्ज करें।','Broken placeholder'=>'टूटा हुआ प्लेसहोल्डर','Build'=>'बिल्ड','Built'=>'बनाया गया','Bulk actions apply only to the selected language of each selected component.'=>'सामूहिक कार्रवाइयाँ चयनित प्रत्येक घटक की केवल चयनित भाषा पर लागू होती हैं।','Bulk actions apply to every matching language of each selected component.'=>'सामूहिक कार्रवाइयाँ चयनित प्रत्येक घटक की सभी मेल खाने वाली भाषाओं पर लागू होती हैं।','Bulk download:'=>'थोक डाउनलोड:','Bulk request:'=>'थोक अनुरोध:','Bulk update:'=>'थोक अपडेट:','Bundled with the plugin'=>'प्लगइन के साथ बंडल किया गया','Bundled with the theme'=>'थीम के साथ बंडल किया गया','By clicking Enable, you agree to send the information listed above to Babilim.'=>'सक्षम करें पर क्लिक करके, आप ऊपर सूचीबद्ध जानकारी Babilim को भेजने के लिए सहमत होते हैं।','By continuing you confirm that you have the right to upload this component.'=>'जारी रखकर आप पुष्टि करते हैं कि आपको इस घटक को अपलोड करने का अधिकार है।','Cancel'=>'रद्द करें','Category'=>'श्रेणी','Check again'=>'फिर से जाँचें','Check again now'=>'अभी फिर से जाँचें','Checkout is not available for this site right now.'=>'इस साइट के लिए अभी भुगतान उपलब्ध नहीं है।','Choose'=>'चुनें','Choose a category…'=>'श्रेणी चुनें…','Choose a language'=>'भाषा चुनें','Choose a language…'=>'भाषा चुनें…','Clear filters'=>'फ़िल्टर्स साफ़ करें','Close'=>'बंद करें','Component'=>'घटक','Confirm'=>'पुष्टि करें','Conflicting keys'=>'टकराने वाली कुंजियाँ','Continue'=>'जारी रखें','Continue next batch (%d left)'=>'अगला बैच जारी रखें (%d शेष)','Continuing…'=>'जारी है…','Could not back up %s before replacing it.'=>'%s को बदलने से पहले उसका बैकअप नहीं लिया जा सका।','Could not create the package archive.'=>'पैकेज आर्काइव नहीं बनाया जा सका।','Could not determine active components; the existing merged index was left unchanged.'=>'सक्रिय कॉम्पोनेंट निर्धारित नहीं किए जा सके; मौजूदा मर्ज्ड इंडेक्स को अपरिवर्तित छोड़ दिया गया।','Could not determine installed plugins/themes; sweep skipped, nothing was deleted.'=>'स्थापित प्लगइन/थीम निर्धारित नहीं किए जा सके; स्वीप छोड़ दिया गया, कुछ भी नहीं हटाया गया।','Could not load the full WordPress.org locale list from the service, so no other language can be added right now.'=>'सेवा से WordPress.org की पूरी लोकेल सूची लोड नहीं हो सकी, इसलिए अभी कोई अन्य भाषा नहीं जोड़ी जा सकती।','Could not move %s into place.'=>'%s को उसकी जगह पर नहीं ले जाया जा सका।','Could not move the merged index for \'%s\' into place; the previous served index (if any) was removed rather than left half-updated. No default-domain supplement is served for this locale until the next successful rebuild.'=>'\'%s\' की मर्ज की गई अनुक्रमणिका को उसकी जगह पर नहीं ले जाया जा सका; पिछली उपयोग में आ रही अनुक्रमणिका (यदि थी) को अधूरी अपडेट रहने देने के बजाय हटा दिया गया। अगले सफल पुनर्निर्माण तक इस लोकेल के लिए कोई डिफ़ॉल्ट-डोमेन पूरक उपलब्ध नहीं कराया जाएगा।','Could not open zip: %s'=>'zip नहीं खोली जा सकी: %s','Could not prepare %s for rollback.'=>'%s को रोलबैक के लिए तैयार नहीं किया जा सका।','Could not read %s back after moving it into place.'=>'%s को जगह पर ले जाने के बाद उसे वापस पढ़ा नहीं जा सका।','Could not read: %s'=>'पढ़ा नहीं जा सका: %s','Could not restore the purchase: %s'=>'खरीद पुनर्स्थापित नहीं की जा सकी: %s','Could not show a new restore code: %s'=>'नया रीस्टोर कोड नहीं दिखाया जा सका: %s','Could not stage %s'=>'%s को स्टेज नहीं किया जा सका','Could not stage default/%s'=>'default/%s को स्टेज नहीं किया जा सका','Could not start checkout: %s'=>'भुगतान शुरू नहीं किया जा सका: %s','Could not verify entry count for %s'=>'%s के लिए प्रविष्टि संख्या सत्यापित नहीं की जा सकी','Could not write the downloaded package to disk.'=>'डाउनलोड किए गए पैकेज को डिस्क पर नहीं लिखा जा सका।','Could not write the staged merged index.'=>'चरणबद्ध मर्ज की गई अनुक्रमणिका नहीं लिखी जा सकी।','Current translation'=>'वर्तमान अनुवाद','Danger zone'=>'खतरनाक क्षेत्र','Default supplement entry count mismatch.'=>'डिफ़ॉल्ट पूरक की प्रविष्टि संख्या मेल नहीं खाती।','Delete all Babilim data on uninstall'=>'अनइंस्टॉल करने पर Babilim का सारा डेटा हटाएँ','Disable Babilim'=>'Babilim अक्षम करें','Disable Babilim? Installed translations are kept, but no further checks or downloads will run.'=>'Babilim अक्षम करें? स्थापित अनुवाद बने रहेंगे, लेकिन आगे कोई जाँच या डाउनलोड नहीं होगा।','Don\'t share'=>'Don\'t share','Download'=>'डाउनलोड करें','Downloaded and installed.'=>'डाउनलोड और स्थापित हो गया।','Downloading…'=>'डाउनलोड हो रहा है…','Downloads: %1$d/%2$d (%3$s)'=>'डाउनलोड: %1$d/%2$d (%3$s)','Each component\'s own contribution to each locale\'s shared default-domain supplement.'=>'प्रत्येक घटक का अपना योगदान, हर लोकेल के साझा डिफ़ॉल्ट-डोमेन पूरक में।','Enable Babilim'=>'Babilim सक्षम करें','Enabling…'=>'सक्षम किया जा रहा है…','English (United States)'=>'अंग्रेज़ी (संयुक्त राज्य अमेरिका)','Entries'=>'प्रविष्टियाँ','Entry count mismatch for %s'=>'%s के लिए प्रविष्टि संख्या मेल नहीं खाती','Error reports'=>'त्रुटि रिपोर्ट','Every locale in use on this site (site locale, installed language packs, user locales, and any you add manually). No locale is treated differently from another.'=>'इस साइट पर उपयोग में आने वाली प्रत्येक लोकेल (साइट लोकेल, स्थापित भाषा पैक, उपयोगकर्ता लोकेल, और वे जो आप मैन्युअल रूप से जोड़ें)। किसी भी लोकेल के साथ अलग व्यवहार नहीं किया जाता।','Excluded'=>'बहिष्कृत','Files with other names or extensions are not included, nor are the uploads, cache, logs, backup, data, vendor, node_modules and languages folders, hidden files, or files whose names match common secrets (wp-config*, .env*, *.sql, *.log, *.pem, *.key). Code files can still contain text or data you would not want to share; check them if you are unsure. The service removes the same kinds of files again on arrival.'=>'अन्य नामों या एक्सटेंशन वाली फ़ाइलें शामिल नहीं की जातीं, और न ही uploads, cache, logs, backup, data, vendor, node_modules और languages फ़ोल्डर, छिपी हुई फ़ाइलें, या ऐसी फ़ाइलें जिनके नाम सामान्य गोपनीय फ़ाइलों से मेल खाते हैं (wp-config*, .env*, *.sql, *.log, *.pem, *.key)। कोड फ़ाइलों में भी ऐसा टेक्स्ट या डेटा हो सकता है जिसे आप साझा नहीं करना चाहेंगे; यदि संदेह हो तो उन्हें जाँच लें। सेवा पहुँचने पर इसी तरह की फ़ाइलें फिर से हटा देती है।','Free'=>'निःशुल्क','Free-plan slots'=>'निःशुल्क प्लान स्लॉट','General'=>'सामान्य','If this is on, uninstalling also erases this site\'s identity. The paid license attached to this site cannot be restored automatically afterwards; you would have to contact Babilim support at %s to get it back.'=>'यदि यह चालू है, तो अनइंस्टॉल करने पर इस साइट की पहचान भी मिट जाती है। इसके बाद इस साइट से जुड़ा सशुल्क लाइसेंस अपने-आप बहाल नहीं किया जा सकता; उसे वापस पाने के लिए आपको %s पर Babilim सहायता से संपर्क करना होगा।','Included'=>'शामिल','Included in index'=>'अनुक्रमणिका में शामिल','Install available translations automatically'=>'उपलब्ध अनुवाद स्वचालित रूप से इंस्टॉल करें','Installed'=>'स्थापित','Installed translations are kept, but no further checks or downloads will run.'=>'स्थापित अनुवाद रखे जाते हैं, लेकिन आगे कोई जाँच या डाउनलोड नहीं चलेगा।','Installed · %s'=>'स्थापित · %s','Installed · built for %1$s, this site has %2$s'=>'स्थापित · %1$s के लिए बनाया गया, इस साइट पर %2$s है','Installed · built for %s'=>'स्थापित · %s के लिए बनाया गया','Installed · built for %s, new version failed'=>'स्थापित · %s के लिए बना, नया संस्करण विफल रहा','Installed · built for %s, new version scheduled'=>'स्थापित · %s के लिए बनाया गया, नया संस्करण निर्धारित है','Installed · built for %s, translating the new version…'=>'स्थापित · %s के लिए बनाया गया, नए संस्करण का अनुवाद हो रहा है…','Installed · built for %s; this plugin or theme is no longer covered by the site\'s service plan'=>'स्थापित · %s के लिए बनाया गया; यह प्लगइन या थीम अब साइट की सेवा योजना में शामिल नहीं है','Installed · built for a different version'=>'स्थापित · किसी भिन्न संस्करण के लिए बनाया गया','Installed · built for a different version, new version failed'=>'स्थापित · किसी अन्य संस्करण के लिए बना, नया संस्करण विफल रहा','Installed · built for a different version, new version scheduled'=>'स्थापित · किसी भिन्न संस्करण के लिए बनाया गया, नया संस्करण निर्धारित है','Installed · built for a different version, translating the new version…'=>'स्थापित · किसी भिन्न संस्करण के लिए बनाया गया, नए संस्करण का अनुवाद हो रहा है…','Installed · built for a different version; this plugin or theme is no longer covered by the site\'s service plan'=>'स्थापित · किसी भिन्न संस्करण के लिए बनाया गया; यह प्लगइन या थीम अब साइट की सेवा योजना में शामिल नहीं है','It is stored by the service\'s hosting provider and processed by AI models to produce the translation.'=>'इसे सेवा के होस्टिंग प्रदाता द्वारा संग्रहीत किया जाता है और अनुवाद तैयार करने के लिए AI मॉडल द्वारा संसाधित किया जाता है।','Language'=>'भाषा','Language:'=>'भाषा:','Languages'=>'भाषाएँ','Languages found on this site: %s.'=>'इस साइट पर मिली भाषाएँ: %s।','Last cleanup on %1$s: %2$d newly marked, %3$d file(s) deleted, %4$d record(s) removed.'=>'पिछली सफाई %1$s को हुई: %2$d फाइलें नई चिह्नित की गईं, %3$d फाइलें हटाई गईं, %4$d रिकॉर्ड हटाए गए।','Maintenance'=>'रखरखाव','Maintenance status is not available right now.'=>'रखरखाव की स्थिति अभी उपलब्ध नहीं है।','Manifest unavailable: %s'=>'मैनिफ़ेस्ट उपलब्ध नहीं है: %s','Negation reversed'=>'नकारात्मकता उलट दी गई','No'=>'नहीं','No build is available to download for this locale.'=>'इस लोकेल के लिए डाउनलोड करने हेतु कोई बिल्ड उपलब्ध नहीं है।','No cleanup has run yet.'=>'अभी तक कोई सफाई नहीं चली है।','No components match these filters. %s'=>'कोई कॉम्पोनेंट इन फ़िल्टर्स से मेल नहीं खाता। %s','No components synced yet.'=>'अभी तक कोई कॉम्पोनेंट सिंक नहीं हुआ।','No installed translation matches.'=>'कोई स्थापित अनुवाद मेल नहीं खाता।','No language is managed yet.'=>'अभी तक कोई भाषा प्रबंधित नहीं है।','No pending challenge for this nonce.'=>'इस नॉन्स के लिए कोई लंबित चुनौती नहीं है।','No pending challenge to verify.'=>'सत्यापित करने के लिए कोई लंबित चैलेंज नहीं है।','No plugins or themes found.'=>'कोई प्लगइन या थीम नहीं मिली।','No previous build to roll back to.'=>'रोलबैक करने के लिए कोई पिछला बिल्ड नहीं है।','No record for %s'=>'%s के लिए कोई रिकॉर्ड नहीं है','No site id is on file to rotate a token for.'=>'टोकन रोटेट करने के लिए कोई साइट आईडी दर्ज नहीं है।','No — component inactive'=>'नहीं — घटक निष्क्रिय है','No — component removed'=>'नहीं — घटक हटा दिया गया है','No — installed version differs from the active one'=>'नहीं — स्थापित संस्करण सक्रिय संस्करण से अलग है','Not a valid server_build_id: %s'=>'अमान्य server_build_id: %s','Not covered by the free service plan'=>'निःशुल्क सेवा प्लान में शामिल नहीं','Not installed'=>'स्थापित नहीं है','Not registered yet'=>'अभी तक पंजीकृत नहीं','Not supported'=>'समर्थित नहीं','Not verified'=>'सत्यापित नहीं','Note (optional)'=>'टिप्पणी (वैकल्पिक)','Nothing to choose.'=>'चुनने के लिए कुछ नहीं है।','Nothing to confirm.'=>'पुष्टि करने के लिए कुछ नहीं है।','Off by default: deleting the plugin keeps this site\'s identity, so a reinstall can reuse it.'=>'डिफ़ॉल्ट रूप से बंद: प्लगइन हटाने पर भी इस साइट की पहचान रखी जाती है, ताकि दोबारा इंस्टॉल करने पर उसका फिर से उपयोग हो सके।','One or more served files no longer match the manifest.'=>'परोसी गई एक या अधिक फाइलें अब मैनिफ़ेस्ट से मेल नहीं खातीं।','One-time purchase for this site: %1$s %2$s. Includes all future translation updates. Payment is handled by Paddle in a new tab.'=>'इस साइट के लिए एकमुश्त खरीद: %1$s %2$s। इसमें भविष्य के सभी अनुवाद अपडेट शामिल हैं। भुगतान नए टैब में Paddle द्वारा संभाला जाता है।','Only a network administrator can do this, because it changes translation files shared by every site on this network.'=>'यह केवल नेटवर्क व्यवस्थापक कर सकता है, क्योंकि इससे इस नेटवर्क की हर साइट द्वारा साझा की जाने वाली अनुवाद फ़ाइलें बदलती हैं।','Only plugins and themes can be packaged.'=>'केवल प्लगइन और थीम ही पैकेज किए जा सकते हैं।','Only when you confirm an upload for a plugin or theme that is not on WordPress.org: every .php and .js file, every block.json file, and the readme.txt, readme.md, style.css and theme.json in that component\'s main folder, as a zip, after files that match common secrets are left out.'=>'केवल तब जब आप WordPress.org पर उपलब्ध न होने वाले प्लगइन या थीम के अपलोड की पुष्टि करते हैं: हर .php और .js फ़ाइल, हर block.json फ़ाइल, और उस कॉम्पोनेंट के मुख्य फ़ोल्डर में मौजूद readme.txt, readme.md, style.css तथा theme.json, सामान्य गोपनीय फ़ाइलों से मेल खाने वाली फ़ाइलों को छोड़ने के बाद, zip के रूप में।','Open Babilim settings'=>'Babilim सेटिंग्स खोलें','Original language'=>'मूल भाषा','Original string'=>'वास्तविक स्ट्रिंग','Paid'=>'सशुल्क','Partner'=>'पार्टनर','Please check that your site can be reached from the internet, then try again.'=>'कृपया जाँचें कि आपकी साइट इंटरनेट से पहुँचने योग्य है, फिर पुनः प्रयास करें।','Please choose a category for this report.'=>'कृपया इस रिपोर्ट के लिए एक श्रेणी चुनें।','Plugin'=>'प्लगइन','Plugin · %s'=>'प्लगइन · %s','Plugins'=>'प्लगइन','Preview'=>'पूर्वावलोकन','Purchase restored. This site is now licensed.'=>'खरीद पुनर्स्थापित हो गई। यह साइट अब लाइसेंस प्राप्त है।','Re-parsed entry count did not match the built index.'=>'दोबारा पार्स की गई प्रविष्टियों की संख्या बनाए गए इंडेक्स से मेल नहीं खाई।','Re-verify'=>'पुनः सत्यापित करें','Rebuild index now'=>'इंडेक्स अभी दोबारा बनाएँ','Refusing to write outside the Babilim language-file directory.'=>'Babilim की भाषा-फ़ाइल निर्देशिका के बाहर लिखने से इनकार किया गया।','Registration response was missing required fields.'=>'पंजीकरण प्रतिक्रिया में आवश्यक फ़ील्ड गायब थे।','Registration restarted.'=>'पंजीकरण फिर से शुरू किया गया।','Remove'=>'हटाएँ','Remove everything Babilim installed'=>'Babilim द्वारा स्थापित सब कुछ हटाएँ','Remove everything Babilim installed? This deletes every language file it installed for every plugin and theme on this site.'=>'Babilim द्वारा स्थापित सब कुछ हटाएँ? इससे इस साइट पर हर प्लगइन और थीम के लिए इसके द्वारा स्थापित सभी भाषा फाइलें हट जाएँगी।','Remove the %2$s translation of %1$s from this site?'=>'इस साइट से %1$s का %2$s भाषा में अनुवाद हटाएँ?','Removed %d installed component.'=>'%d स्थापित घटक हटाया गया।' . "\0" . '%d स्थापित घटक हटाए गए।','Removed after a failed integrity check'=>'अखंडता जाँच विफल होने के बाद हटाया गया','Removed.'=>'हटा दिया गया।','Removes every language file Babilim has installed for every plugin and theme on this site.'=>'इस साइट पर हर प्लगइन और थीम के लिए Babilim द्वारा स्थापित सभी भाषा फाइलें हटा देता है।','Report a problem'=>'समस्या की रिपोर्ट करें','Report translation'=>'अनुवाद की रिपोर्ट करें','Request newer translation'=>'नए अनुवाद का अनुरोध करें','Request translation'=>'अनुवाद का अनुरोध करें','Requestable'=>'अनुरोध योग्य','Requesting a translation puts this plugin or theme on one of the free service plan\'s slots for this site (the limit is %1$d for themes and %2$d for plugins), unless it already has one. A slot stays used, and a failed translation does not free it.'=>'अनुवाद का अनुरोध करने पर यह प्लगइन या थीम इस साइट के लिए निःशुल्क सेवा योजना के किसी एक स्लॉट पर आ जाती है (सीमा थीम के लिए %1$d और प्लगइन के लिए %2$d है), जब तक कि वह पहले से किसी स्लॉट पर न हो। स्लॉट उपयोग में ही रहता है, और असफल अनुवाद से भी वह मुक्त नहीं होता।','Requesting a translation puts this plugin or theme on one of the free service plan\'s slots for this site, unless it already has one. A slot stays used, and a failed translation does not free it.'=>'अनुवाद का अनुरोध करने पर यह प्लगइन या थीम इस साइट के लिए निःशुल्क सेवा योजना के किसी एक स्लॉट पर आ जाती है, जब तक कि वह पहले से किसी स्लॉट पर न हो। स्लॉट उपयोग में ही रहता है, और असफल अनुवाद से भी वह मुक्त नहीं होता।','Requesting…'=>'अनुरोध किया जा रहा है…','Restart registration'=>'पंजीकरण फिर से शुरू करें','Restore code'=>'रीस्टोर कोड','Restore purchase'=>'खरीद पुनर्स्थापित करें','Retry request'=>'अनुरोध दोबारा करें','Roll back'=>'रोल बैक करें','Roll back and report'=>'रोल बैक करें और रिपोर्ट करें','Roll back and send report'=>'रोलबैक करें और रिपोर्ट भेजें','Roll back the %2$s translation of %1$s to the previous build?'=>'क्या %1$s के %2$s अनुवाद को पिछले बिल्ड पर रोलबैक करें?','Rolled back and reported.'=>'रोलबैक किया गया और रिपोर्ट भेजी गई।','Rolled back to the previous build.'=>'पिछले बिल्ड पर रोलबैक किया गया।','Rolled back, but the report could not be sent: %s'=>'रोलबैक किया गया, लेकिन रिपोर्ट नहीं भेजी जा सकी: %s','Rolling back would overwrite \'%1$s\' (%2$s), which is now served for another installed component (%3$s); nothing was changed.'=>'रोलबैक करने से \'%1$s\' (%2$s) ओवरराइट हो जाएगी, जो अब किसी अन्य स्थापित घटक (%3$s) के लिए परोसी जा रही है; कुछ भी नहीं बदला गया।','Rotate-token response was missing site_token.'=>'टोकन बदलने की प्रतिक्रिया में site_token अनुपलब्ध था।','Save changes'=>'बदलाव सहेजें','Scheduled, waiting to be processed'=>'निर्धारित, प्रोसेस होने की प्रतीक्षा में','Search'=>'खोजें','Search components'=>'कॉम्पोनेंट खोजें','Search the installed translations'=>'स्थापित अनुवादों में खोजें','Select all'=>'सभी चुनें','Select fewer components: at most %1$d operations per run (you selected %2$d).'=>'कम कॉम्पोनेंट चुनें: प्रति रन अधिकतम %1$d ऑपरेशन (आपने %2$d चुने हैं)।','Send report'=>'रिपोर्ट भेजें','Service plan'=>'सेवा प्लान','Settings'=>'सेटिंग्स','Share error reports'=>'त्रुटि रिपोर्ट साझा करें','Share this report'=>'इस रिपोर्ट को साझा करें','Show a new restore code'=>'नया रीस्टोर कोड दिखाएँ','Show the "Report translation" entry in the admin toolbar'=>'एडमिन टूलबार में "Report translation" एंट्री दिखाएँ','Some of this component\'s text is hard-coded by its author and can\'t be translated by a language pack.'=>'इस घटक के कुछ टेक्स्ट इसके लेखक द्वारा सीधे कोड में लिखे गए हैं और भाषा पैक द्वारा अनुवादित नहीं किए जा सकते।','Status'=>'स्थिति','Status unknown'=>'स्थिति अज्ञात','String context'=>'स्ट्रिंग संदर्भ','Suggested translation'=>'सुझाया गया अनुवाद','Supplementary translation index'=>'पूरक अनुवाद अनुक्रमणिका','Supplementary translation index rebuilt.'=>'पूरक अनुवाद अनुक्रमणिका फिर से बनाई गई।','Supplementary translation maintenance'=>'पूरक अनुवाद रखरखाव','Supplementary translations'=>'पूरक अनुवाद','Sweep aborted without orphaning anything: %s.'=>'किसी को भी अनाथ किए बिना स्वीप रोक दिया गया: %s।','Sweep complete: %d file deleted.'=>'सफाई पूरी हुई: %d फाइल हटाई गई।' . "\0" . 'सफाई पूरी हुई: %d फाइलें हटाई गईं।','Sweep now'=>'अभी स्वीप करें','Sync complete.'=>'सिंक पूर्ण हुआ।','Thank you. Your report was sent.'=>'धन्यवाद। आपकी रिपोर्ट भेज दी गई है।','That component is not installed on this site, so a translation cannot be requested for it.'=>'वह घटक इस साइट पर स्थापित नहीं है, इसलिए उसके लिए अनुवाद का अनुरोध नहीं किया जा सकता।','That does not look like a restore code.'=>'यह रीस्टोर कोड जैसा नहीं दिखता।','That is not a valid WordPress locale code. Nothing was saved.'=>'यह मान्य WordPress लोकेल कोड नहीं है। कुछ भी सहेजा नहीं गया।','That is not a valid build identifier.'=>'यह मान्य बिल्ड पहचानकर्ता नहीं है।','That upload screen was out of date: a different upload has been prepared since. Nothing was sent. Review the current one from the Translations list.'=>'वह अपलोड स्क्रीन पुरानी हो चुकी थी: तब से एक अलग अपलोड तैयार किया गया है। कुछ भी नहीं भेजा गया। वर्तमान अपलोड को अनुवाद सूची से देखें।','The change could not be recorded in the translation index; please try again.'=>'यह बदलाव अनुवाद अनुक्रमणिका में दर्ज नहीं हो सका; कृपया फिर से प्रयास करें।','The cleanup ran, but some of its changes could not be recorded in the translation index; the next cleanup will retry them.'=>'सफ़ाई चली, लेकिन इसके कुछ बदलाव अनुवाद अनुक्रमणिका में दर्ज नहीं किए जा सके; अगली सफ़ाई उन्हें दोबारा आज़माएगी।','The component has no files that can be uploaded.'=>'इस कॉम्पोनेंट में अपलोड करने योग्य कोई फ़ाइल नहीं है।','The component is not inside the plugins or themes directory.'=>'घटक प्लगइन या थीम डायरेक्टरी के अंदर नहीं है।','The component\'s main file was not found.'=>'घटक की मुख्य फाइल नहीं मिली।','The download response was missing a usable location.'=>'डाउनलोड प्रतिक्रिया में कोई उपयोग योग्य स्थान नहीं था।','The entry opens a panel to search the translations Babilim installed on this site and report one of them.'=>'यह एंट्री एक पैनल खोलती है, जिसमें Babilim द्वारा इस साइट पर स्थापित अनुवाद खोजे और उनमें से किसी की रिपोर्ट की जा सकती है।','The field "%1$s" is too long: it has %2$d characters and the limit is %3$d. Nothing was sent; please shorten it and try again.'=>'फ़ील्ड "%1$s" बहुत लंबा है: इसमें %2$d वर्ण हैं और सीमा %3$d है। कुछ भी नहीं भेजा गया; कृपया इसे छोटा करें और पुनः प्रयास करें।','The free service plan gives each site a limited number of slots for plugins and themes; the slots in use are shown in Settings after you enable Babilim.'=>'निःशुल्क सेवा योजना हर साइट को प्लगइन और थीम के लिए सीमित संख्या में स्लॉट देती है; उपयोग में आ रहे स्लॉट Babilim सक्षम करने के बाद सेटिंग्स में दिखाई देते हैं।','The given domain \'%1$s\' matches neither the package manifest\'s own slug \'%2$s\' nor its text_domain \'%3$s\'.'=>'दिया गया डोमेन \'%1$s\' न तो पैकेज के मैनिफ़ेस्ट के अपने स्लग \'%2$s\' से मेल खाता है और न ही उसके text_domain \'%3$s\' से।','The merged index for \'%s\' was rebuilt, but the translation index could not record it; the next rebuild will retry.'=>'\'%s\' की मर्ज की गई अनुक्रमणिका फिर से बनाई गई, लेकिन अनुवाद अनुक्रमणिका उसे दर्ज नहीं कर सकी; अगला पुनर्निर्माण दोबारा प्रयास करेगा।','The original text and the translations made from it will be provided to other sites that install the same version.'=>'मूल पाठ और उससे बने अनुवाद उन अन्य साइटों को उपलब्ध कराए जाएँगे जो यही संस्करण इंस्टॉल करती हैं।','The package declares no main translation file.'=>'पैकेज में कोई मुख्य अनुवाद फाइल घोषित नहीं है।','The package has no %s for its own text domain.'=>'पैकेज में अपने स्वयं के टेक्स्ट डोमेन के लिए कोई %s नहीं है।','The package manifest\'s kind \'%1$s\' does not match the requested kind \'%2$s\'.'=>'पैकेज के मैनिफ़ेस्ट का प्रकार \'%1$s\' अनुरोधित प्रकार \'%2$s\' से मेल नहीं खाता।','The package produced no servable main translation file.'=>'पैकेज से कोई परोसी जा सकने वाली मुख्य अनुवाद फाइल नहीं बनी।','The package\'s text domain \'%1$s\' does not match this site\'s copy of the component (\'%2$s\'), so it was not installed.'=>'पैकेज का टेक्स्ट डोमेन \'%1$s\' इस साइट के घटक की प्रति (\'%2$s\') से मेल नहीं खाता, इसलिए इसे स्थापित नहीं किया गया।','The packaged component could not be read.'=>'पैकेज किया गया घटक पढ़ा नहीं जा सका।','The registration challenge is not in the expected form.'=>'पंजीकरण चैलेंज अपेक्षित रूप में नहीं है।','The report could not be sent.'=>'रिपोर्ट भेजी नहीं जा सकी।','The search could not be completed.'=>'खोज पूरी नहीं हो सकी।','The service asked this site to wait before syncing again.'=>'सेवा ने इस साइट से दोबारा सिंक करने से पहले प्रतीक्षा करने को कहा।','The service could not reach your site. A firewall, security plugin or host rule is probably blocking the request; please allow requests to /wp-json/babilim/v1/challenge.'=>'सेवा आपकी साइट तक नहीं पहुँच सकी। संभवतः कोई फ़ायरवॉल, सुरक्षा प्लगइन या होस्ट नियम अनुरोध को रोक रहा है; कृपया /wp-json/babilim/v1/challenge के अनुरोधों की अनुमति दें।','The service\'s upload offer was incomplete.'=>'सेवा का अपलोड प्रस्ताव अधूरा था।','The text domain \'%1$s\' (%2$s) is already served for another installed component (%3$s); nothing was installed.'=>'टेक्स्ट डोमेन \'%1$s\' (%2$s) पहले से किसी अन्य स्थापित घटक (%3$s) के लिए परोसा जा रहा है; कुछ भी स्थापित नहीं किया गया।','The upload is kept until you ask Babilim to delete it.'=>'अपलोड तब तक रखा जाता है जब तक आप Babilim से उसे हटाने के लिए नहीं कहते।','Theme'=>'थीम','Theme · %s'=>'थीम · %s','Themes'=>'थीम','There is no upload in progress.'=>'कोई अपलोड प्रगति पर नहीं है।','There is no upload waiting for confirmation.'=>'पुष्टि की प्रतीक्षा में कोई अपलोड नहीं है।','These are the languages this site uses. You can change them in %s.'=>'ये वे भाषाएँ हैं जिनका उपयोग यह साइट करती है। आप इन्हें %s में बदल सकते हैं।','These fields will be sent:'=>'ये फ़ील्ड भेजे जाएँगे:','This build is not one this site currently knows about for this component/locale.'=>'यह बिल्ड ऐसा नहीं है जिसे यह साइट इस घटक/लोकेल के लिए वर्तमान में जानती हो।','This component does not declare a version number, so a translation cannot be requested for it.'=>'यह घटक कोई संस्करण संख्या घोषित नहीं करता, इसलिए इसके लिए अनुवाद का अनुरोध नहीं किया जा सकता।','This component is larger than the service accepts, so it cannot be uploaded.'=>'यह घटक सेवा द्वारा स्वीकार किए जाने वाले आकार से बड़ा है, इसलिए इसे अपलोड नहीं किया जा सकता।','This component was already uploaded. Babilim is checking it now.'=>'यह घटक पहले ही अपलोड किया जा चुका है। Babilim अभी इसकी जाँच कर रहा है।','This component\'s version number is longer than %d characters, which Babilim cannot handle, so a translation cannot be requested for it.'=>'इस घटक की संस्करण संख्या %d अक्षरों से अधिक लंबी है, जिसे Babilim संभाल नहीं सकता, इसलिए इसके लिए अनुवाद का अनुरोध नहीं किया जा सकता।','This issues a new restore code and the previous one stops working. Continue?'=>'इससे एक नया रीस्टोर कोड जारी होगा और पिछला कोड काम करना बंद कर देगा। जारी रखें?','This network has too many sites to check them one by one, and some of them may be set to erase their Babilim identity when the plugin is deleted. The paid license attached to such a site could then not be restored automatically; you would have to contact Babilim support at %s. To keep the identities, press Cancel, untick "Delete all Babilim data on uninstall" in each site\'s Babilim settings, and deactivate again. Deactivate anyway?'=>'इस नेटवर्क में इतनी अधिक साइटें हैं कि उन्हें एक-एक करके जाँचा नहीं जा सकता, और उनमें से कुछ प्लगइन हटाए जाने पर अपनी Babilim पहचान मिटाने के लिए सेट हो सकती हैं। तब ऐसी साइट से जुड़ा सशुल्क लाइसेंस अपने-आप बहाल नहीं किया जा सकेगा; आपको %s पर Babilim सहायता से संपर्क करना होगा। पहचानें बनाए रखने के लिए रद्द करें दबाएँ, हर साइट की Babilim सेटिंग्स में "अनइंस्टॉल करने पर Babilim का सारा डेटा हटाएँ" का चयन हटाएँ, और फिर से निष्क्रिय करें। फिर भी निष्क्रिय करें?','This plugin\'s own version, so the service can tell you to update it if it\'s too old to talk to.'=>'इस प्लगइन का अपना संस्करण, ताकि बहुत पुराना होने पर सेवा आपको इसे अपडेट करने के लिए कह सके।','This report does not name a valid plugin or theme and locale.'=>'यह रिपोर्ट किसी मान्य प्लगइन या थीम और लोकेल का नाम नहीं बताती।','This report does not name an installed string.'=>'यह रिपोर्ट किसी स्थापित स्ट्रिंग का नाम नहीं बताती।','This report is missing a valid build to report against.'=>'इस रिपोर्ट में रिपोर्ट करने के लिए कोई मान्य बिल्ड नहीं है।','This report will be posted publicly on GitHub and may be kept by third parties.'=>'यह रिपोर्ट GitHub पर सार्वजनिक रूप से पोस्ट की जाएगी और तृतीय पक्षों द्वारा रखी जा सकती है।','This restore code was not recognised for this site.'=>'यह रीस्टोर कोड इस साइट के लिए पहचाना नहीं गया।','This site already has an active registration that can no longer be recovered automatically.'=>'इस साइट का एक सक्रिय पंजीकरण पहले से है, जिसे अब स्वचालित रूप से पुनर्प्राप्त नहीं किया जा सकता।','This site has %1$d components across %2$d languages, which needs %3$d check batches; Babilim can handle at most %4$d per run. Reduce the managed languages in Settings or deactivate unused plugins and themes, then press Check again now.'=>'इस साइट में %2$d भाषाओं में %1$d घटक हैं, जिनके लिए %3$d जाँच बैच चाहिए; Babilim प्रति रन अधिकतम %4$d बैच संभाल सकता है। सेटिंग्स में प्रबंधित भाषाएँ कम करें या अप्रयुक्त प्लगइन और थीम निष्क्रिय करें, फिर अभी फिर से जाँचें दबाएँ।','This site has no purchase to show a code for.'=>'इस साइट की कोई खरीद नहीं है जिसका कोड दिखाया जा सके।','This site is already licensed. Reload the page.'=>'इस साइट का लाइसेंस पहले से है। पृष्ठ को रीलोड करें।','This site is not registered with Babilim yet.'=>'यह साइट अभी तक Babilim के साथ पंजीकृत नहीं है।','This site is over the size the service accepts in one sync, so some items were left out: %1$d components and %2$d locales.'=>'यह साइट उस आकार से बड़ी है जिसे सेवा एक सिंक में स्वीकार करती है, इसलिए कुछ आइटम छोड़ दिए गए: %1$d कॉम्पोनेंट और %2$d लोकेल।','This site is part of a multisite network, which does not install new translations automatically. Translations that are already installed are still updated.'=>'यह साइट एक मल्टीसाइट नेटवर्क का हिस्सा है, जो नए अनुवाद स्वचालित रूप से इंस्टॉल नहीं करता। पहले से स्थापित अनुवाद फिर भी अपडेट किए जाते हैं।','This site is verified.'=>'यह साइट सत्यापित है।','This site must be verified first.'=>'इस साइट को पहले सत्यापित करना आवश्यक है।','This site\'s URL, so the service can verify you own it.'=>'इस साइट का यूआरएल, ताकि सेवा सत्यापित कर सके कि यह आपकी है।','This site\'s address is too long for Babilim to register.'=>'इस साइट का पता Babilim द्वारा पंजीकृत करने के लिए बहुत लंबा है।','This site\'s configured locale.'=>'इस साइट की कॉन्फ़िगर की गई लोकेल।','This site\'s locale code is not one Babilim can register.'=>'इस साइट का लोकेल कोड ऐसा नहीं है जिसे Babilim पंजीकृत कर सके।','This string can\'t be reported from this site.'=>'इस स्ट्रिंग की रिपोर्ट इस साइट से नहीं की जा सकती।','This string is not among the translations installed on this site. Search again and pick it from the list.'=>'यह स्ट्रिंग इस साइट पर स्थापित अनुवादों में शामिल नहीं है। फिर से खोजें और सूची से इसे चुनें।','This translation was updated since you searched. Search again and pick the string from the new list.'=>'आपके खोजने के बाद यह अनुवाद अपडेट हो गया है। फिर से खोजें और नई सूची से स्ट्रिंग चुनें।','To translate this component, Babilim needs its source.'=>'इस घटक का अनुवाद करने के लिए Babilim को इसका स्रोत चाहिए।','Too many attempts. Try again tomorrow.'=>'बहुत अधिक प्रयास। कल फिर कोशिश करें।','Too many reports today. Try again tomorrow.'=>'आज बहुत अधिक रिपोर्ट हो गई हैं। कल फिर प्रयास करें।','Too many requests.'=>'बहुत अधिक अनुरोध।','Toolbar'=>'टूलबार','Translating…'=>'अनुवाद हो रहा है…','Translation does not load'=>'अनुवाद लोड नहीं होता','Translation failed'=>'अनुवाद विफल रहा','Translation requested.'=>'अनुवाद का अनुरोध किया गया।','Translations'=>'अनुवाद','Type'=>'प्रकार','Type at least 2 characters to search.'=>'खोजने के लिए कम से कम 2 अक्षर टाइप करें।','Unexpected HTTP %d response.'=>'अप्रत्याशित HTTP %d प्रतिक्रिया।','Uninstall'=>'अनइंस्टॉल','Unknown kind: %s'=>'अज्ञात kind: %s','Unsafe domain: %s'=>'असुरक्षित डोमेन: %s','Unsafe locale: %s'=>'असुरक्षित लोकेल: %s','Unsafe slug: %s'=>'असुरक्षित स्लग: %s','Unsafe text_domain: %s'=>'असुरक्षित text_domain: %s','Update'=>'अपडेट करें','Update available'=>'अपडेट उपलब्ध है','Updates'=>'अपडेट','Updating…'=>'अपडेट हो रहा है…','Upgrade this site'=>'इस साइट को अपग्रेड करें','Upload and request'=>'अपलोड करें और अनुरोध करें','Upload cancelled.'=>'अपलोड रद्द किया गया।','Upload complete — translation requested.'=>'अपलोड पूरा हुआ — अनुवाद का अनुरोध किया गया।','Upload expired before it finished'=>'अपलोड पूरा होने से पहले ही समाप्त हो गया','Upload in progress — continue or cancel'=>'अपलोड जारी है — जारी रखें या रद्द करें','Upload this component?'=>'क्या इस घटक को अपलोड करें?','Upload was not accepted'=>'अपलोड स्वीकार नहीं किया गया','Uploading'=>'अपलोड हो रहा है','Uploading part %1$d of %2$d…'=>'भाग %1$d / %2$d अपलोड हो रहा है…','Uploading…'=>'अपलोड हो रहा है…','Verified'=>'सत्यापित','Verify response was missing site_token.'=>'सत्यापन प्रतिक्रिया में site_token अनुपलब्ध था।','Version %s'=>'संस्करण %s','What is sent when you enable Babilim'=>'Babilim सक्षम करने पर क्या भेजा जाता है','Where you saw this (optional)'=>'आपने इसे कहाँ देखा (वैकल्पिक)','While this is on, translations the service lists as available for the languages you manage are installed during the twice-daily sync.'=>'इसके चालू रहने पर, आपके द्वारा प्रबंधित भाषाओं के लिए सेवा द्वारा उपलब्ध बताए गए अनुवाद दिन में दो बार होने वाले सिंक के दौरान स्थापित किए जाते हैं।','WordPress.org'=>'WordPress.org','Wrong for this context'=>'इस संदर्भ के लिए गलत','Wrong meaning'=>'गलत अर्थ','Wrong plural form'=>'गलत बहुवचन रूप','Wrong term'=>'गलत शब्द','Yes'=>'हाँ','You are not allowed to do this.'=>'आपको यह कार्य करने की अनुमति नहीं है।','Your PHP version, for compatibility.'=>'आपका PHP संस्करण, संगतता के लिए।','Your WordPress version, to serve compatible translation files.'=>'आपका WordPress संस्करण, ताकि संगत अनुवाद फ़ाइलें उपलब्ध कराई जा सकें।','Your new restore code: %s. Keep it somewhere safe — the previous code no longer works.'=>'आपका नया रीस्टोर कोड: %s। इसे सुरक्षित जगह रखें — पिछला कोड अब काम नहीं करता।','Your report is processed automatically by AI models and may improve this translation for other sites.'=>'आपकी रिपोर्ट को AI मॉडल द्वारा स्वचालित रूप से संसाधित किया जाता है और इससे अन्य साइटों के लिए इस अनुवाद को बेहतर बनाने में मदद मिल सकती है।','Your site answered, but not with what was expected. The REST API may be rewritten by another plugin, or that endpoint may be cached; please exclude /wp-json/babilim/v1/challenge from caching and rewriting.'=>'आपकी साइट ने उत्तर तो दिया, पर अपेक्षित उत्तर नहीं। हो सकता है REST API को किसी अन्य प्लगइन ने बदल दिया हो, या वह एंडपॉइंट कैश हो रहा हो; कृपया /wp-json/babilim/v1/challenge को कैशिंग और रीराइटिंग से बाहर रखें।','Your site took too long to answer. Please try again later, and check that your host is not too slow or overloaded.'=>'आपकी साइट ने उत्तर देने में बहुत समय लिया। कृपया बाद में पुनः प्रयास करें, और जाँचें कि आपका होस्ट बहुत धीमा या ओवरलोडेड तो नहीं है।','Zip has no manifest.json.'=>'Zip में manifest.json नहीं है।','Zip is missing expected default file: %s'=>'Zip में अपेक्षित डिफ़ॉल्ट फाइल गायब है: %s','Zip is missing expected file: %s'=>'Zip में अपेक्षित फाइल गायब है: %s','_manifest.json has an unexpected structure'=>'_manifest.json की संरचना अपेक्षित नहीं है','could not read _manifest.json: %s'=>'_manifest.json नहीं पढ़ा जा सका: %s','expected_manifest is missing or has an invalid \'%s\'.'=>'expected_manifest में \'%s\' अनुपलब्ध है या अमान्य है।','expected_manifest\'s \'server_build_id\' is not a valid build id.'=>'expected_manifest का \'server_build_id\' एक मान्य बिल्ड आईडी नहीं है।','failed to parse _manifest.json: %s'=>'_manifest.json को पार्स करने में विफल: %s','it would orphan %1$d of %2$d managed components (more than half)'=>'यह %2$d प्रबंधित घटकों में से %1$d को अनाथ कर देगा (आधे से अधिक)','it would orphan every managed %1$s component (%2$d of %2$d)'=>'यह प्रत्येक प्रबंधित %1$s घटक को अनाथ कर देगा (%2$d में से %2$d)','l10n.php entry count mismatch for %s'=>'%s के लिए l10n.php प्रविष्टियों की संख्या बेमेल','manifest.json has an invalid \'default_domain_entries\'.'=>'manifest.json में \'default_domain_entries\' अमान्य है।','manifest.json has an invalid \'default_domain_files\'.'=>'manifest.json में \'default_domain_files\' अमान्य है।','manifest.json in the zip is not valid JSON.'=>'zip में manifest.json मान्य JSON नहीं है।','manifest.json is missing or has an invalid \'%s\'.'=>'manifest.json में \'%s\' अनुपलब्ध है या अमान्य है।','manifest.json is missing or has an invalid \'build_no\'.'=>'manifest.json में \'build_no\' अनुपलब्ध है या अमान्य है।','manifest.json is missing or has an invalid \'entries\'.'=>'manifest.json में \'entries\' अनुपलब्ध है या अमान्य है।','manifest.json is missing or has an invalid \'extra_domains\'.'=>'manifest.json में \'extra_domains\' अनुपलब्ध है या अमान्य है।','manifest.json is missing or has an invalid \'files\'.'=>'manifest.json में \'files\' अनुपलब्ध है या अमान्य है।','manifest.json\'s \'%s\' does not match the expected value.'=>'manifest.json का \'%s\' अपेक्षित मान से मेल नहीं खाता।','manifest.json\'s \'contract\' is not a valid version string.'=>'manifest.json का \'contract\' एक मान्य संस्करण स्ट्रिंग नहीं है।','manifest.json\'s \'kind\' must be \'plugin\' or \'theme\'.'=>'manifest.json का \'kind\' \'plugin\' या \'थीम\' (\'theme\') होना चाहिए।','manifest.json\'s \'server_build_id\' is not a valid build id.'=>'manifest.json का \'server_build_id\' एक मान्य बिल्ड आईडी नहीं है।','manifest.json\'s \'status\' must be \'published\'.'=>'manifest.json का \'status\' \'प्रकाशित\' (\'published\') होना चाहिए।','nonce must be a hexadecimal string.'=>'नॉन्स एक हेक्साडेसिमल स्ट्रिंग होना चाहिए।','per day'=>'प्रति दिन','rc_…'=>'rc_…','sha256 mismatch for %s'=>'%s के लिए sha256 बेमेल','sha256 mismatch for default/%s'=>'default/%s के लिए sha256 बेमेल','component kind in the sweep brake messageplugin'=>'प्लगइन','component kind in the sweep brake messagetheme'=>'थीम','problem report categoryOther'=>'अन्य','translation statusAvailable'=>'उपलब्ध','translation statusInstalled'=>'स्थापित','Babilim translation turned off.'=>'Babilim अनुवाद बंद कर दिया गया।','Stop using Babilim translation'=>'Babilim अनुवाद का उपयोग बंद करें','Use Babilim translation'=>'Babilim अनुवाद का उपयोग करें','Stop using the Babilim translation of %1$s (%2$s)? WordPress will use the theme\'s own or WordPress.org translation instead. You can switch back at any time.'=>'%1$s (%2$s) के Babilim अनुवाद का उपयोग बंद करें? WordPress इसके बजाय थीम के अपने या WordPress.org के अनुवाद का उपयोग करेगा। आप किसी भी समय वापस स्विच कर सकते हैं।','Stop using the Babilim translation of %1$s (%2$s)? WordPress will use the plugin\'s own or WordPress.org translation instead. You can switch back at any time.'=>'%1$s (%2$s) के Babilim अनुवाद का उपयोग बंद करें? WordPress इसके बजाय प्लगइन के अपने या WordPress.org के अनुवाद का उपयोग करेगा। आप किसी भी समय वापस स्विच कर सकते हैं।','Enjoying Babilim? Please leave a rating on WordPress.org.'=>'क्या आपको Babilim पसंद आ रहा है? कृपया WordPress.org पर रेटिंग दें।','Rate Babilim'=>'Babilim को रेट करें','Babilim translation bundled with the theme'=>'थीम के साथ बंडल किया गया Babilim अनुवाद','Babilim translation bundled with the plugin'=>'प्लगइन के साथ बंडल किया गया Babilim अनुवाद','For every installed plugin and theme: its name (slug), version, text domain, whether it is listed on WordPress.org, the languages it already includes, and which of those bundled translations Babilim generated (language codes only). For each Babilim translation you have installed: which version it is, when it was last checked, and whether it passed its file check.'=>'हर स्थापित प्लगइन और थीम के लिए: उसका नाम (स्लग), संस्करण, text domain, क्या वह WordPress.org पर सूचीबद्ध है, उसमें पहले से शामिल भाषाएँ, और उन बंडल किए गए अनुवादों में से कौन-से Babilim ने बनाए (केवल भाषा कोड)। आपके द्वारा स्थापित किए गए प्रत्येक Babilim अनुवाद के लिए: वह कौन-सा संस्करण है, उसकी आखिरी जांच कब हुई, और क्या वह अपनी फाइल जांच में सफल रहा।','Working…'=>'काम जारी है…','Babilim could not finish this. Reload the page and try again.'=>'Babilim इसे पूरा नहीं कर सका। पृष्ठ को पुनः लोड करें और फिर से प्रयास करें।','This translation does not have the number of forms the language needs.'=>'इस अनुवाद में उतने रूप नहीं हैं जितने भाषा को चाहिए।','This translation is empty.'=>'यह अनुवाद खाली है।','The text has invalid characters or control characters.'=>'टेक्स्ट में अमान्य वर्ण या नियंत्रण वर्ण हैं।','The HTML tags must match the original: same tags, each opened and closed as in the original.'=>'HTML टैग मूल पाठ के समान होने चाहिए: टैग वही हों और हर टैग मूल पाठ की तरह ही खोला और बंद किया गया हो।','The translation has %s, which the original does not. Keep the placeholders of the original; to write a plain percent sign next to a letter, add a space or write %%%%.'=>'अनुवाद में %s है, जो मूल पाठ में नहीं है। मूल पाठ के प्लेसहोल्डर बनाए रखें; किसी अक्षर के बगल में सामान्य प्रतिशत चिह्न लिखने के लिए स्पेस जोड़ें या %%%% लिखें।','The translation has a lone percent sign that would break the text. Write 100%% for a literal percent sign.'=>'अनुवाद में एक अकेला प्रतिशत चिह्न है जो टेक्स्ट को तोड़ देगा। शाब्दिक प्रतिशत चिह्न के लिए 100%% लिखें।','Unsafe override scope.'=>'असुरक्षित ओवरराइड स्कोप।','The override files could not be written.'=>'ओवरराइड फ़ाइलें नहीं लिखी जा सकीं।','That plugin, theme, text domain or language is not available here.'=>'वह प्लगइन, थीम, टेक्स्ट डोमेन या भाषा यहाँ उपलब्ध नहीं है।','The editor could not complete that request.'=>'संपादक यह अनुरोध पूरा नहीं कर सका।','The translation did not pass the checks, so it was not saved. Your text is kept as a draft.'=>'अनुवाद जाँच में सफल नहीं हुआ, इसलिए सहेजा नहीं गया। आपका टेक्स्ट ड्राफ़्ट के रूप में रखा गया है।','The table that stores edited translations does not exist yet.'=>'संपादित अनुवाद संग्रहीत करने वाली तालिका अभी मौजूद नहीं है।','That plugin or theme is not installed.'=>'वह प्लगइन या थीम स्थापित नहीं है।','That string is not in this translation.'=>'वह स्ट्रिंग इस अनुवाद में नहीं है।','The translation could not be saved.'=>'अनुवाद सहेजा नहीं जा सका।','Edit translations'=>'अनुवाद संपादित करें','Edit translations: %1$s, %2$s'=>'अनुवाद संपादित करें: %1$s, %2$s','There is nothing to edit yet. Install a plugin or theme, or add a language, and it shows up here.'=>'अभी संपादित करने के लिए कुछ नहीं है। कोई प्लगइन या थीम इंस्टॉल करें, या कोई भाषा जोड़ें, वह यहाँ दिखाई देगी।','Choose a plugin or theme and a language to edit its translation.'=>'किसी प्लगइन या थीम और भाषा को चुनें और उसका अनुवाद संपादित करें।','Name'=>'नाम','Edit'=>'संपादित करें','Back to all plugins and themes'=>'सभी प्लगइन और थीम पर वापस जाएँ','Text domain'=>'टेक्स्ट डोमेन','Show'=>'दिखाएँ','The editor needs JavaScript. Everything else in Babilim works without it.'=>'संपादक को JavaScript की आवश्यकता है। Babilim में बाकी सब कुछ इसके बिना काम करता है।','Untranslated'=>'अनुवादित नहीं','Needs review'=>'समीक्षा आवश्यक','No longer used'=>'अब उपयोग में नहीं','From Babilim'=>'Babilim से','From WordPress.org'=>'WordPress.org से','From the plugin or theme'=>'प्लगइन या थीम से','Save'=>'सहेजें','You are logged out. Log in again in another tab, then press Save.'=>'आप लॉग आउट हो गए हैं। किसी दूसरे टैब में फिर से लॉग इन करें, फिर सहेजें दबाएँ।','This text is not saved yet. It stays in the field.'=>'यह टेक्स्ट अभी सहेजा नहीं गया है। यह फ़ील्ड में बना रहता है।','Form %d'=>'रूप %d','Translation'=>'अनुवाद','Original text'=>'वास्तविक टेक्स्ट','Context'=>'संदर्भ','Note for translators'=>'अनुवादकों के लिए नोट','Previous page'=>'पिछला पृष्ठ','Next page'=>'अगला पृष्ठ','Page %1$d of %2$d'=>'पृष्ठ %1$d / %2$d','No more untranslated strings on this page.'=>'इस पृष्ठ पर अब ऐसी कोई स्ट्रिंग नहीं बची है जिसका अनुवाद न हुआ हो।','No strings match.'=>'कोई स्ट्रिंग मेल नहीं खाती।','No strings found. This plugin or theme does not ship a translation template.'=>'कोई स्ट्रिंग नहीं मिली। यह प्लगइन या थीम अनुवाद टेम्पलेट के साथ नहीं आता।','The translation file could not be written yet. It is tried again automatically every day.'=>'अनुवाद फाइल अभी नहीं लिखी जा सकी। इसे हर दिन अपने-आप फिर से आज़माया जाता है।','Edit this text'=>'इस टेक्स्ट को संपादित करें','Has problems'=>'समस्याएँ हैं','%d string'=>'%d स्ट्रिंग' . "\0" . '%d स्ट्रिंग','%d untranslated'=>'%d अनुवाद बाकी' . "\0" . '%d अनुवाद बाकी','%d edited by you'=>'%d आपके द्वारा संपादित' . "\0" . '%d आपके द्वारा संपादित','%d change is live.'=>'%d बदलाव लाइव है।' . "\0" . '%d बदलाव लाइव हैं।','%d change is saved.'=>'%d बदलाव सहेजा गया।' . "\0" . '%d बदलाव सहेजे गए।','%d draft needs fixing and was not saved.'=>'%d ड्राफ़्ट में सुधार की ज़रूरत है और उसे सहेजा नहीं गया।' . "\0" . '%d ड्राफ़्ट में सुधार की ज़रूरत है और उन्हें सहेजा नहीं गया।','%d change could not be saved.'=>'%d बदलाव सहेजा नहीं जा सका।' . "\0" . '%d बदलाव सहेजे नहीं जा सके।','Nothing to save.'=>'सहेजने के लिए कुछ नहीं है।','Save %d change'=>'%d बदलाव सहेजें' . "\0" . '%d बदलाव सहेजें','%d draft saved, not live yet'=>'%d ड्राफ़्ट सहेजा गया, अभी लाइव नहीं है' . "\0" . '%d ड्राफ़्ट सहेजे गए, अभी लाइव नहीं हैं','%d needs fixing and stays a draft'=>'%d में सुधार की ज़रूरत है और वह ड्राफ़्ट ही रहेगा' . "\0" . '%d में सुधार की ज़रूरत है और वे ड्राफ़्ट ही रहेंगे','Discard %d draft? Your live translations stay as they are.'=>'%d ड्राफ़्ट हटाएँ? आपके लाइव अनुवाद जैसे हैं वैसे ही रहेंगे।' . "\0" . '%d ड्राफ़्ट हटाएँ? आपके लाइव अनुवाद जैसे हैं वैसे ही रहेंगे।','%s (theme)'=>'%s (थीम)','Plugin or theme'=>'प्लगइन या थीम','Discard drafts…'=>'ड्राफ़्ट हटाएँ…','Show strings'=>'स्ट्रिंग दिखाएँ','Text, context, notes or file name'=>'टेक्स्ट, संदर्भ, नोट्स या फ़ाइल का नाम','Searches the original text, the translation, the context, notes for translators and the file the string comes from.'=>'वास्तविक टेक्स्ट, अनुवाद, संदर्भ, अनुवादकों के लिए नोट्स और उस फ़ाइल में खोजता है जहाँ से स्ट्रिंग आई है।','Sort'=>'क्रमबद्ध करें','Default'=>'डिफ़ॉल्ट','Untranslated first'=>'अनुवाद रहित पहले','Recently edited'=>'हाल ही में संपादित','A–Z'=>'A–Z','Source'=>'स्रोत','All sources'=>'सभी स्रोत','Original'=>'वास्तविक','Edit the selected string'=>'चुनी हुई स्ट्रिंग संपादित करें','Details and history'=>'विवरण और इतिहास','Edited by you'=>'आपके द्वारा संपादित','Form %1$d: %2$s'=>'रूप %1$d: %2$s','Translation (%s)'=>'अनुवाद (%s)','This language uses one form for every number.'=>'यह भाषा हर संख्या के लिए एक ही रूप इस्तेमाल करती है।','Plural forms'=>'बहुवचन रूप','empty'=>'खाली','problem'=>'समस्या','Original (singular)'=>'वास्तविक (एकवचन)','Original (plural)'=>'वास्तविक (बहुवचन)','Copy original'=>'वास्तविक टेक्स्ट कॉपी करें','Details'=>'विवरण','History'=>'इतिहास','WordPress.org language pack'=>'WordPress.org भाषा पैक','Bundled with the plugin or theme'=>'प्लगइन या थीम के साथ बंडल किया हुआ','Yours (edited by you)'=>'आपका (आपके द्वारा संपादित)','Found in'=>'इसमें मिला','Restore'=>'पुनर्स्थापित करें','Live'=>'लाइव','Draft'=>'ड्राफ़्ट','Draft · Problem'=>'ड्राफ़्ट · समस्या','Bundled'=>'बंडल किया हुआ','Yours'=>'आपका','(plural)'=>'(बहुवचन)','Discard this draft'=>'इस ड्राफ़्ट को हटाएँ','Drafts discarded.'=>'ड्राफ़्ट हटा दिए गए।','Draft discarded.'=>'ड्राफ़्ट हटा दिया गया।','This draft is kept, but it does not go live with Save until it is fixed. Your other changes still go live.'=>'यह ड्राफ़्ट रखा गया है, लेकिन जब तक इसे ठीक नहीं किया जाता, यह सहेजने पर लाइव नहीं होगा। आपके बाकी बदलाव फिर भी लाइव होंगे।','Draft saved at %s. Not live yet.'=>'ड्राफ़्ट %s बजे सहेजा गया। अभी लाइव नहीं है।','Visitors still see the live text until you press Save.'=>'जब तक आप सहेजें नहीं दबाते, विज़िटर को लाइव टेक्स्ट ही दिखता रहेगा।','Live now: %1$s (%2$s)'=>'अभी लाइव: %1$s (%2$s)','Ctrl'=>'Ctrl','Enter'=>'Enter','next string'=>'अगली स्ट्रिंग','previous / next'=>'पिछली / अगली','copy original'=>'वास्तविक टेक्स्ट कॉपी करें','clear'=>'साफ़ करें','Open'=>'खोलें','Babilim – Auto Translation & Language Packs'=>'Babilim – ऑटो अनुवाद और भाषा पैक','Auto-translate every plugin and theme on your site, then fine-tune any line in a fast built-in editor. Your edits survive updates.'=>'अपनी साइट के हर प्लगइन और थीम का अपने आप अनुवाद करें, फिर तेज़ बिल्ट-इन एडिटर में किसी भी पंक्ति को बेहतर बनाएँ। आपके संपादन अपडेट के बाद भी सुरक्षित रहते हैं।','%d change to review'=>'%d बदलाव की समीक्षा बाकी है' . "\0" . '%d बदलावों की समीक्षा बाकी है','No translation yet'=>'अभी तक कोई अनुवाद नहीं','The original text changed in %1$s %2$s.'=>'%1$s %2$s में वास्तविक टेक्स्ट बदल गया है।','Your translation was written for the old text, so the site no longer shows it. Choose what to use for the new text.'=>'आपका अनुवाद पुराने टेक्स्ट के लिए लिखा गया था, इसलिए साइट अब इसे नहीं दिखाती। चुनें कि नए टेक्स्ट के लिए क्या उपयोग करना है।','Old original'=>'पुराना वास्तविक टेक्स्ट','New original'=>'नया वास्तविक टेक्स्ट','Your translation (for the old text)'=>'आपका अनुवाद (पुराने टेक्स्ट के लिए)','Your current translation'=>'आपका वर्तमान अनुवाद','Use my text'=>'मेरा टेक्स्ट उपयोग करें','New translation from %s'=>'%s से नया अनुवाद','Use the new translation'=>'नए अनुवाद का उपयोग करें','Keep my current translation'=>'मेरा वर्तमान अनुवाद रखें','Discard my text'=>'मेरा टेक्स्ट हटाएँ','Whichever you choose becomes a draft and goes live with Save, like any other change.'=>'आप जो भी चुनें, वह किसी अन्य बदलाव की तरह ड्राफ़्ट बन जाता है और सहेजने पर लाइव हो जाता है।','Or edit it yourself'=>'या खुद संपादित करें','This text is no longer used: %1$s %2$s does not have this string any more.'=>'यह टेक्स्ट अब उपयोग में नहीं है: %1$s %2$s में अब यह स्ट्रिंग नहीं है।','Delete…'=>'हटाएँ…','Delete your translation of this text? It is not shown anywhere on the site.'=>'क्या इस टेक्स्ट का आपका अनुवाद हटाना है? यह साइट पर कहीं नहीं दिखता।','Translation deleted.'=>'अनुवाद हटा दिया गया।','That text is still in use, so it cannot be removed here.'=>'वह टेक्स्ट अभी उपयोग में है, इसलिए उसे यहाँ से हटाया नहीं जा सकता।','%1$s – %2$s'=>'%1$s – %2$s','Removed text:'=>'हटाया गया टेक्स्ट:','Added text:'=>'जोड़ा गया टेक्स्ट:','When something fails inside Babilim, send an error report to the Babilim service: what failed, where and when, a random report ID, the versions and the site language. Only the error, where it happened and the versions are published as a public issue on GitHub; the public issue contains no site address, content or file paths. Off by default.'=>'जब Babilim के अंदर कुछ विफल होता है, तो Babilim सेवा को एक त्रुटि रिपोर्ट भेजें: क्या विफल हुआ, कहाँ और कब, एक यादृच्छिक रिपोर्ट ID, संस्करण और साइट की भाषा। केवल त्रुटि, वह कहाँ हुई और संस्करण GitHub पर सार्वजनिक समस्या के रूप में प्रकाशित किए जाते हैं; सार्वजनिक समस्या में साइट का पता, सामग्री या फ़ाइल पथ शामिल नहीं होते। डिफ़ॉल्ट रूप से बंद।','Translation edits'=>'अनुवाद संपादन','Share my edits with Babilim'=>'मेरे संपादन Babilim के साथ साझा करें','When you change a translation that came from Babilim, your version is sent with the original text, Babilim\'s translation, the plugin or theme, the language and the build. Babilim processes it with AI models and may use it to improve that translation for every site. Off by default.'=>'जब आप Babilim से आए किसी अनुवाद को बदलते हैं, तो आपका संस्करण मूल टेक्स्ट, Babilim के अनुवाद, प्लगइन या थीम, भाषा और बिल्ड के साथ भेजा जाता है। Babilim इसे AI मॉडल से प्रोसेस करता है और हर साइट के लिए उस अनुवाद को बेहतर बनाने में इसका उपयोग कर सकता है। डिफ़ॉल्ट रूप से बंद।','Your own translations'=>'आपके अपने अनुवाद','Keep my translations when removing everything or uninstalling Babilim.'=>'सब कुछ हटाते समय या Babilim को अनइंस्टॉल करते समय मेरे अनुवाद रखें।','Your edits and the files you put in %s always take priority over Babilim\'s. Unchecking this deletes them when you remove everything or uninstall.'=>'आपके संपादन और %s में रखी गई आपकी फ़ाइलें हमेशा Babilim के अनुवादों पर प्राथमिकता रखती हैं। इसे अनचेक करने पर सब कुछ हटाते या अनइंस्टॉल करते समय वे हट जाएँगी।','Files: %s.'=>'फ़ाइलें: %s।','Imported: %s.'=>'आयात किए गए: %s।','Already identical: %s.'=>'पहले से समान: %s।','Kept your existing translation: %s.'=>'आपका मौजूदा अनुवाद रखा गया: %s।','Imported, but no longer used in this version: %s.'=>'आयात किए गए, लेकिन इस संस्करण में अब उपयोग में नहीं: %s।','Kept as drafts to fix: %s.'=>'सुधारने के लिए ड्राफ़्ट के रूप में रखे गए: %s।','Skipped: %s.'=>'छोड़े गए: %s।','Review the import'=>'आयात की समीक्षा करें','Loco Translate\'s files are not changed. Deactivate Loco Translate yourself when you are ready.'=>'Loco Translate की फ़ाइलें नहीं बदली गई हैं। जब आप तैयार हों, Loco Translate को स्वयं निष्क्रिय करें।','Import from Loco Translate'=>'Loco Translate से आयात करें','Found %s Loco Translate file you can import.'=>'%s Loco Translate फ़ाइल मिली जिसे आप आयात कर सकते हैं।' . "\0" . '%s Loco Translate फ़ाइलें मिलीं जिन्हें आप आयात कर सकते हैं।','Get the text list from Babilim'=>'Babilim से टेक्स्ट सूची प्राप्त करें','Sends the plugin\'s or theme\'s name and version to Babilim.'=>'प्लगइन या थीम का नाम और संस्करण Babilim को भेजता है।','Babilim is preparing the list. This takes a few minutes.'=>'Babilim सूची तैयार कर रहा है। इसमें कुछ मिनट लगते हैं।','Enable Babilim to get the text list for this plugin or theme.'=>'इस प्लगइन या थीम की टेक्स्ट सूची प्राप्त करने के लिए Babilim सक्षम करें।','Babilim cannot list the text of this plugin or theme: it is not on WordPress.org and it ships no translation template.'=>'Babilim इस प्लगइन या थीम के टेक्स्ट की सूची नहीं बना सकता: यह WordPress.org पर नहीं है और इसके साथ कोई अनुवाद टेम्पलेट नहीं आता।','Babilim found no translatable text in this version.'=>'Babilim को इस संस्करण में अनुवाद योग्य कोई टेक्स्ट नहीं मिला।','The editor session has expired.'=>'संपादक सत्र समाप्त हो गया है।','That plugin or theme is not available here.'=>'वह प्लगइन या थीम यहाँ उपलब्ध नहीं है।','Some Loco Translate files could not be read.'=>'कुछ Loco Translate फ़ाइलें पढ़ी नहीं जा सकीं।','This plugin or theme is not on WordPress.org.'=>'यह प्लगइन या थीम WordPress.org पर नहीं है।','Babilim returned an invalid text list.'=>'Babilim ने अमान्य टेक्स्ट सूची लौटाई।','The text list could not be saved.'=>'टेक्स्ट सूची सहेजी नहीं जा सकी।']];